query:
CREATE TABLE `menu_items` (
	`id` int AUTO_INCREMENT NOT NULL,
	`menuId` int NOT NULL,
	`label` varchar(128) NOT NULL,
	`url` varchar(512) NOT NULL,
	`target` enum('_self','_blank') NOT NULL DEFAULT '_self',
	`sortOrder` int NOT NULL DEFAULT 0,
	`parentId` int,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `menu_items_id` PRIMARY KEY(`id`)
);

CREATE TABLE `menus` (
	`id` int AUTO_INCREMENT NOT NULL,
	`location` enum('main','footer','mobile') NOT NULL,
	`label` varchar(128) NOT NULL,
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `menus_id` PRIMARY KEY(`id`),
	CONSTRAINT `menus_location_unique` UNIQUE(`location`)
);

CREATE TABLE `site_settings` (
	`id` int AUTO_INCREMENT NOT NULL,
	`key` varchar(128) NOT NULL,
	`value` text,
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `site_settings_id` PRIMARY KEY(`id`),
	CONSTRAINT `site_settings_key_unique` UNIQUE(`key`)
);

CREATE TABLE `static_pages` (
	`id` int AUTO_INCREMENT NOT NULL,
	`slug` varchar(128) NOT NULL,
	`title` varchar(256) NOT NULL,
	`content` text,
	`seoTitle` varchar(256),
	`seoDescription` text,
	`status` enum('draft','published') NOT NULL DEFAULT 'draft',
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `static_pages_id` PRIMARY KEY(`id`),
	CONSTRAINT `static_pages_slug_unique` UNIQUE(`slug`)
);

ALTER TABLE `categories` ADD `coverKey` text;
ALTER TABLE `categories` ADD `seoTitle` varchar(256);
ALTER TABLE `categories` ADD `seoDescription` text;
ALTER TABLE `categories` ADD `sortOrder` int DEFAULT 0 NOT NULL;
ALTER TABLE `categories` ADD `updatedAt` timestamp DEFAULT (now()) NOT NULL ON UPDATE CURRENT_TIMESTAMP;

CREATE INDEX `idx_menu_items_menuId` ON `menu_items` (`menuId`);
CREATE INDEX `idx_menu_items_sortOrder` ON `menu_items` (`sortOrder`);

